@contextmanager
def windows_cached_direntry_stats():
    """Model documented Windows DirEntry zero IDs; real stat/handles stay real."""
    original_scandir = os.scandir

    class Entry:
        def __init__(self, entry): self.entry = entry
        def __getattr__(self, name): return getattr(self.entry, name)
        def stat(self, **options):
            result = self.entry.stat(**options)
            fields = {name: getattr(result, name) for name in dir(result) if name.startswith("st_")}
            fields.update(st_ino=0, st_dev=0, st_nlink=0)
            return SimpleNamespace(**fields)

    class Scan:
        def __init__(self, scan): self.scan = scan
        def __enter__(self): self.scan.__enter__(); return self
        def __exit__(self, *arguments): return self.scan.__exit__(*arguments)
        def __iter__(self): return self
        def __next__(self): return Entry(next(self.scan))
        def close(self): return self.scan.close()

    def scan(*arguments, **options): return Scan(original_scandir(*arguments, **options))

    with mock.patch.object(diagnostics.os, "scandir", side_effect=scan):
        yield
